@classmethod
def exact(
    cls,
    policy_id: str,
    purpose: str,
    command: Sequence[str],
    *,
    forbidden_program_names: Sequence[str] = (),
) -> "ProcessPolicy":
    forbidden = {
        name.strip().casefold()
        for name in forbidden_program_names
        if name.strip()
    }
    return cls(
        policy_id=policy_id,
        purpose=purpose,
        allowed_commands=(tuple(command),),
        forbidden_program_names=frozenset(
            {*_FORBIDDEN_AGENT_PROGRAM_NAMES, *forbidden}
        ),
    )

def validate(self, command: Sequence[str]) -> None:
    selected = tuple(command)
    if selected not in self.allowed_commands:
        raise ProcessExecutionError(
            "policy_denied",
            "外部程序请求不在调用方精确允许范围内",
            command_name=(Path(command[0]).name if command else ""),
        )
    name = Path(selected[0]).name.casefold()
    identities = {name, Path(name).stem.casefold()}
    if identities & self.forbidden_program_names:
        raise ProcessExecutionError(
            "forbidden_agent_program",
            "受限进程监督禁止启动智能编码代理程序",
            command_name=Path(selected[0]).name,
        )
    if identities & _COMMAND_WRAPPER_PROGRAM_NAMES:
        for token in selected[1:]:
            token_name = Path(token.strip().strip('"')).name.casefold()
            token_identities = {
                token_name,
                Path(token_name).stem.casefold(),
            }
            if token_identities & self.forbidden_program_names:
                raise ProcessExecutionError(
                    "forbidden_agent_wrapper",
                    "受限进程监督禁止通过包装参数启动智能编码代理程序",
                    command_name=Path(selected[0]).name,
                )

@pytest.mark.parametrize(
    ("command", "reason"),
    [
        (["agy", "--version"], "forbidden_agent_program"),
        (["AGY.EXE", "--version"], "forbidden_agent_program"),
        ([sys.executable, "agy"], "forbidden_agent_wrapper"),
        (["powershell.exe", "-Command", "agy.exe", "--version"], "forbidden_agent_wrapper"),
    ],
)
def test_known_antigravity_entry_is_rejected_before_process_start(
    tmp_path: Path, monkeypatch, command: list[str], reason: str,
) -> None:
    def unexpected_start(*args, **kwargs):
        raise AssertionError("agent policy rejection must precede process creation")

    monkeypatch.setattr("strixnova.process_supervisor.subprocess.Popen", unexpected_start)
    with pytest.raises(ProcessExecutionError) as rejected:
        run_process(
            command, cwd=tmp_path,
            policy=ProcessPolicy.exact("test.known-agent-denial", "deny_agent", command),
        )
    assert rejected.value.reason == reason

